    {
      "name": "AddMonoidAlgebra.mul_apply_antidiagonal",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Defs",
      "kind": "theorem",
      "type": "∀ {M : Type u_2} {R : Type u_6} [inst : Semiring R] [inst_1 : Add M] (x y : AddMonoidAlgebra R M) (m : M)\n  (s : Finset (M × M)), (∀ {p : M × M}, p ∈ s ↔ p.1 + p.2 = m) → (x * y) m = ∑ p ∈ s, x p.1 * y p.2"
    },
    {
      "name": "AddMonoidAlgebra.mul_apply",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Defs",
      "kind": "theorem",
      "type": "∀ {M : Type u_2} {R : Type u_6} [inst : Semiring R] [inst_1 : Add M] [inst_2 : DecidableEq M]\n  (x y : AddMonoidAlgebra R M) (m : M),\n  (x * y) m = Finsupp.sum x fun m₁ r₁ => Finsupp.sum y fun m₂ r₂ => if m₁ + m₂ = m then r₁ * r₂ else 0"
    },
    {
      "name": "AddMonoidAlgebra.mul_apply_left",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Defs",
      "kind": "theorem",
      "type": "∀ {G : Type u_1} {R : Type u_6} [inst : Semiring R] [inst_1 : AddGroup G] (x y : AddMonoidAlgebra R G) (g : G),\n  (x * y) g = Finsupp.sum x fun h r => r * y (-h + g)"
    },
